(()=>{'use strict';const $=id=>document.getElementById(id);let challenge;
async function call(path,body){let r=await fetch('/api/auth/admin-bootstrap'+path,{credentials:'same-origin',cache:'no-store',method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'content-type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)})});let b=await r.json();if(!r.ok)throw Error(b.error||'설정을 처리하지 못했어요.');return b}
call('').then(()=>{$('setupStatus').textContent='사이트 소유자 확인 완료 · 아직 생성되지 않은 전용 ID예요.';$('setupContent').hidden=false}).catch(err=>$('setupError').textContent=err.message);
$('startAdminSetup').onclick=async()=>{let button=$('startAdminSetup');button.disabled=true;$('setupError').textContent='';try{let b=await call('/start',{});challenge=b.challengeId;$('adminSetupSecret').value=b.secret;$('completeAdminSetup').hidden=false;button.textContent='등록 키 다시 만들기';$('setupStatus').textContent='10분 안에 인증 앱 등록과 비밀번호 설정을 완료해주세요.'}catch(err){$('setupError').textContent=err.message}finally{button.disabled=false}};
$('copyAdminSecret').onclick=()=>navigator.clipboard.writeText($('adminSetupSecret').value).then(()=>{$('copyAdminSecret').textContent='복사했어요.'}).catch(()=>{$('setupError').textContent='등록 키를 직접 복사해주세요.'});
$('completeAdminSetup').onsubmit=async e=>{e.preventDefault();let button=e.target.querySelector('[type=submit]');button.disabled=true;try{let b=await call('/complete',{challengeId:challenge,password:$('adminSetupPassword').value,confirm:$('adminSetupConfirm').value,code:$('adminSetupCode').value,agree:$('adminSetupAgree').checked});$('adminSetupPassword').value='';$('adminSetupConfirm').value='';$('adminSetupSecret').value='';$('setupContent').hidden=true;$('setupStatus').textContent='최고 관리자 계정을 생성했어요. 복구 코드는 한 번만 표시돼요. 비밀번호 복구용이며 인증 앱을 대신하지 않아요.';let box=document.createElement('section'),code=document.createElement('code'),copy=document.createElement('button'),continueButton=document.createElement('a');code.className='recovery-code';code.textContent=b.recoveryCode;copy.textContent='복구 코드 복사';copy.onclick=()=>navigator.clipboard.writeText(b.recoveryCode).then(()=>copy.textContent='복사했어요.');continueButton.href='/admin';continueButton.className='primary auth-link';continueButton.textContent='관리자 대시보드로';box.append(code,copy,continueButton);$('authGate').append(box)}catch(err){$('setupError').textContent=err.message;button.disabled=false}finally{let pw=$('adminSetupPassword'),confirm=$('adminSetupConfirm');if(pw)pw.value='';if(confirm)confirm.value=''}};
})();
